      "terms": {
        "field": "group_id"
      },
      "aggregations": {
        "items": {
          "terms": {
            "field": "item_id",
            "order": {
              "_key": "desc"
            }
          },
          "aggregations": {
            "value": {
              "sum": {
                "field": "item_value"
              }
            }
          }
        }
      }
    }
  }
}
```

